import{_ as o,o as t,c,a3 as d}from"./chunks/framework.DAK02U1-.js";const _=JSON.parse('{"title":"钩子机制（hook 后端实现）","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"钩子机制（hook 后端实现） | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/catter/design/hook-mechanism"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/catter/design/hook-mechanism"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/catter/design/hook-mechanism"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/catter/design/hook-mechanism"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/catter/design/hook-mechanism"}]]},"headers":[],"relativePath":"zh/catter/design/hook-mechanism.md","filePath":"zh/catter/design/hook-mechanism.md","lastUpdated":1793201601000}'),a={name:"zh/catter/design/hook-mechanism.md"};function r(s,e,i,n,l,p){return t(),c("div",null,[...e[0]||(e[0]=[d(`<h1 id="钩子机制-hook-后端实现" tabindex="-1">钩子机制（hook 后端实现） <a class="header-anchor" href="#钩子机制-hook-后端实现" aria-label="Permalink to &quot;钩子机制（hook 后端实现）&quot;">​</a></h1><blockquote><p>本文描述 <strong>hook 后端</strong>的底层实现，handler 作者通常不需要阅读。它解答的是&quot;命令是如何被捕获的&quot;这一平台细节；handler 关心的能力与限制见<a href="./capture-backends">捕获后端</a>。</p></blockquote><p>钩子是 hook 后端捕获构建所用的载体：一个共享库，被加载到构建系统生成的每个进程中。它拦截进程创建调用。在 Linux 和 macOS 上，它将调用重写，使每个子进程都通过 <code>catter-proxy</code> 中转，而非直接执行；在 Windows 上，它自己向 catter 询问如何处理每次调用，并按 catter 的决定启动程序。</p><p>钩子的实现完全依赖于平台特性。Unix 和 Windows 使用了截然不同的拦截技术。</p><h2 id="unix-linux-与-macos-基于-ld-preload-的拦截" tabindex="-1">Unix（Linux 与 macOS）-- 基于 LD_PRELOAD 的拦截 <a class="header-anchor" href="#unix-linux-与-macos-基于-ld-preload-的拦截" aria-label="Permalink to &quot;Unix（Linux 与 macOS）-- 基于 LD_PRELOAD 的拦截&quot;">​</a></h2><p>Unix 钩子是通过动态链接器的预加载机制加载的共享库：</p><ul><li><strong>Linux</strong>: <code>libcatter-hook-unix.so</code>，通过 <code>LD_PRELOAD</code> 加载</li><li><strong>macOS</strong>: <code>libcatter-hook-unix.dylib</code>，通过 <code>DYLD_INSERT_LIBRARIES</code> 加载</li></ul><h3 id="被拦截的函数" tabindex="-1">被拦截的函数 <a class="header-anchor" href="#被拦截的函数" aria-label="Permalink to &quot;被拦截的函数&quot;">​</a></h3><p>钩子替换了所有用于创建新进程的标准 POSIX 函数：</p><p><strong>exec 系列</strong>:</p><ul><li><code>execve()</code>、<code>execv()</code></li><li><code>execvp()</code>、<code>execvpe()</code>（Linux）、<code>execvP()</code>（macOS）</li><li><code>execl()</code>、<code>execlp()</code>、<code>execle()</code></li></ul><p><strong>posix_spawn 系列</strong>:</p><ul><li><code>posix_spawn()</code></li><li><code>posix_spawnp()</code></li></ul><p>在 Linux 上，钩子使用 <code>dlsym(RTLD_NEXT, &quot;execve&quot;)</code> 从加载顺序中的下一个库获取原始函数指针，然后提供一个签名相同的替换函数。当替换函数被调用时，钩子可以检查和修改参数，然后选择性地调用原始函数。</p><p>在 macOS 上，钩子使用 <code>DYLD_INTERPOSE</code> 宏在 dyld 层面替换函数，这是该平台上的首选技术。</p><p>dyld 会终止无法加载插入库的程序，而钩子是按 catter 自身的架构构建的，Apple 自带的工具（arm64e）和在 Rosetta 下运行的 Intel 程序（x86_64）都不以这个架构运行。插入钩子之前，<code>catter-proxy</code> 先向 dyld 询问程序以哪种架构运行（<code>macho_best_slice</code>；脚本按其解释器计）：架构不同的程序不带钩子运行，它启动的进程不会被捕获。开启系统完整性保护（SIP）时，dyld 同样会从 Apple 的工具中去掉钩子，因此构建只能捕获到它所运行的 Apple 工具为止：<code>/usr/bin/make</code>，或 Ninja 用来运行每条命令的 <code>/bin/sh</code>。</p><h3 id="核心类" tabindex="-1">核心类 <a class="header-anchor" href="#核心类" aria-label="Permalink to &quot;核心类&quot;">​</a></h3><p>钩子由一组协作的类实现：</p><ul><li><strong><code>find_program()</code></strong>（kotatsu）-- 像 exec 函数那样，在 <code>PATH</code> 或当前目录中查找目标可执行文件；程序不存在或无法运行时，像原调用一样失败。</li><li><strong><code>proxy_environment()</code></strong> -- <code>catter-proxy</code> 得到的环境：即程序要求的环境，去掉预加载库中的钩子，并加上指明会话的变量。</li><li><strong><code>Executor</code></strong> -- 协调整个拦截过程。它从库加载时的环境中取得会话，查找可执行文件，再以 <code>catter-proxy</code> 代替原程序调用原始函数；并持有真实 <code>execve</code> / <code>posix_spawn</code> 的函数指针。</li></ul><h3 id="钩子初始化" tabindex="-1">钩子初始化 <a class="header-anchor" href="#钩子初始化" aria-label="Permalink to &quot;钩子初始化&quot;">​</a></h3><p>钩子库通过动态链接器的构造函数机制（<code>on_load</code>，<code>__attribute__((constructor))</code>）加载。初始化期间，库会：</p><ol><li>设置日志（调试构建下输出到 catter 数据目录下的 <code>log/catter-hook.log</code>）</li><li>以环境和真实的 <code>execve</code> / <code>posix_spawn</code> 函数指针调用 <code>Executor::init()</code>（Linux 上经 <code>dlsym(RTLD_NEXT, ...)</code>，macOS 上直接引用系统符号）</li><li>在 Linux 上调用 <code>Executor::restart_undecided()</code>：如果进程的 exec 不是 <code>catter-proxy</code> 启动的，就经 <code>catter-proxy</code> 重新启动这个进程（见下文）</li></ol><h3 id="环境变量" tabindex="-1">环境变量 <a class="header-anchor" href="#环境变量" aria-label="Permalink to &quot;环境变量&quot;">​</a></h3><p>钩子从以下环境变量中读取会话信息。代理带着钩子运行它的命令（<code>RUN</code>）时设置这些变量，其中的命令 ID 就是这条命令自己的 ID：</p><table tabindex="0"><thead><tr><th>变量</th><th>用途</th></tr></thead><tbody><tr><td><code>__key_catter_proxy_path_v1</code></td><td><code>catter-proxy</code> 二进制文件的绝对路径</td></tr><tr><td><code>__key_catter_command_id_v1</code></td><td>进程所运行命令的 ID</td></tr><tr><td><code>__key_catter_ipc_v1</code></td><td>catter 会话的管道</td></tr><tr><td><code>__key_catter_decided_v1</code></td><td>在 Linux 上，<code>catter-proxy</code> 启动进程时所用的 exec，钩子读到后即将其移除</td></tr></tbody></table><h3 id="拦截流程" tabindex="-1">拦截流程 <a class="header-anchor" href="#拦截流程" aria-label="Permalink to &quot;拦截流程&quot;">​</a></h3><p>当任何进程创建函数被调用时（例如 <code>execve(&quot;/usr/bin/g++&quot;, argv, envp)</code>）：</p><ol><li><p>进入钩子的替换函数。</p></li><li><p>如果库加载时的环境中没有指明 <code>catter-proxy</code>，调用原样交给系统：该进程没有会话。</p></li><li><p><strong><code>Executor</code></strong> 用 kotatsu 的 <code>find_program()</code> 查找目标可执行文件。对于 <code>execvp()</code> 和 <code>execvpe()</code> 等函数，它会搜索 <code>PATH</code> 中的目录。对于 <code>execve()</code>，不含 <code>/</code> 的路径从当前目录查找。</p></li><li><p><strong><code>Executor</code></strong> 构造代理命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;proxy_path&gt; &lt;resolved_path&gt; &lt;original_argv...&gt;</span></span></code></pre></div><p>原始的 <code>argv[0]</code> 及所有后续参数跟在解析出的路径之后。</p></li><li><p><strong><code>proxy_environment()</code></strong> 修改环境数组：</p><ul><li>从 <code>LD_PRELOAD</code>（或 <code>DYLD_INSERT_LIBRARIES</code>）中剥离钩子库名称</li><li>如果剥离后 <code>LD_PRELOAD</code> 变为空，则将其完全移除</li><li>放入进程加载时的 <code>__key_catter_ipc_v1</code> 和 <code>__key_catter_command_id_v1</code>，替换程序环境中已有的同名变量：程序可能以自己构造的环境启动另一个程序，如 <code>env -i</code> 那样，<code>catter-proxy</code> 在那里仍能找到它的会话</li></ul></li><li><p><strong><code>Executor</code></strong> 使用重写后的命令调用<strong>真正的</strong> <code>execve()</code>（通过初始化时解析得到的函数指针）。</p></li><li><p>如果 <code>execve</code> 成功，当前进程镜像被替换，函数不会返回。如果失败，钩子恢复 <code>errno</code> 并将错误返回给调用者。</p></li></ol><h3 id="为什么要清理环境" tabindex="-1">为什么要清理环境？ <a class="header-anchor" href="#为什么要清理环境" aria-label="Permalink to &quot;为什么要清理环境？&quot;">​</a></h3><p>这一步至关重要。如果在启动 <code>catter-proxy</code> 时钩子库仍留在 <code>LD_PRELOAD</code> 中：</p><ol><li><code>catter-proxy</code> 本身会被钩住</li><li>当代理尝试执行实际的编译器时，钩子会拦截该调用</li><li>钩子会将其重写为启动另一个 <code>catter-proxy</code></li><li>这将造成<strong>无限递归</strong></li></ol><p>通过从 <code>LD_PRELOAD</code> 中剥离钩子，代理可以不受拦截地执行。代理仅在以 <code>RUN</code> 动作启动命令时才重新添加 <code>LD_PRELOAD</code>，确保钩子仅挂载到正确的进程上。</p><h3 id="递归钩子" tabindex="-1">递归钩子 <a class="header-anchor" href="#递归钩子" aria-label="Permalink to &quot;递归钩子&quot;">​</a></h3><p>由于 <code>LD_PRELOAD</code> 通过环境变量被子进程继承，拦截是自动递归的。考虑如下构建场景：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make</span></span>
<span class="line"><span>  -&gt; sh -c &quot;gcc main.c -o main&quot;</span></span>
<span class="line"><span>     -&gt; gcc main.c -o main</span></span>
<span class="line"><span>        -&gt; cc1 main.c -o main.s</span></span>
<span class="line"><span>        -&gt; as main.s -o main.o</span></span>
<span class="line"><span>        -&gt; ld main.o -o main</span></span></code></pre></div><p>这棵进程树中的每个进程都继承了 <code>LD_PRELOAD</code>，因此都会被钩住。每次调用都会经过 <code>catter-proxy</code>，由守护进程决定如何处理。构建系统完全无法感知到拦截的存在。</p><h3 id="不经钩子启动的程序-linux" tabindex="-1">不经钩子启动的程序（Linux） <a class="header-anchor" href="#不经钩子启动的程序-linux" aria-label="Permalink to &quot;不经钩子启动的程序（Linux）&quot;">​</a></h3><p>静态程序不加载钩子，Go 的运行时自己发起系统调用：它们启动的程序（例如 bazelisk 启动 Bazel，<code>go build</code> 启动 cgo 的 C 编译器）来自钩子看不到的 exec。<code>LD_PRELOAD</code> 仍会传到这些程序，钩子照样加载进每一个，然后由它们自行上报：</p><ol><li><code>catter-proxy</code> 给它按决定启动的每个程序设置 <code>__key_catter_decided_v1</code>：它自己的 pid，以及 <code>argv[0]</code> 之后参数的个数和哈希。内核经解释器运行脚本时，这些参数仍留在 <code>argv</code> 末尾；<code>catter-proxy</code> 经 <code>/bin/sh</code> 运行没有可执行格式的文件时也是如此。</li><li>钩子的构造函数把这个变量从环境中取出，让它只对应一次 exec，再拿它与自己的进程比对：父进程是那个 <code>catter-proxy</code>，且 <code>argv</code> 以那些参数结尾。</li><li>比对一致的进程照常运行。不一致的进程（构建中某个程序启动的子进程，或替换掉 <code>catter-proxy</code> 所启动程序的程序）会以 <code>catter-proxy</code> 的身份重新启动，带上自己的程序（exec 所指的文件，脚本则为运行它的解释器）、<code>argv</code>、环境以及 <code>__key_catter_late_v1</code>。<code>catter-proxy</code> 像对待其他命令一样上报它，作为 <code>__key_catter_command_id_v1</code> 所指命令的子命令，并按决定运行。决定运行时，程序带着钩子重新启动，这时它的变量只写 <code>catter-proxy</code> 的 pid，因此不会再次重启；被丢弃时，程序不运行，以退出码 0 结束。</li></ol><p>此时程序自己的代码还没有运行：运行过的只有它所链接的库的构造函数，重启后它们会再运行一次。有些进程不会重启：以动态加载器为程序运行的进程（<code>ld.so &lt;program&gt;</code>），其 <code>argv</code> 已去掉加载器自己的参数；valgrind 在自己的进程中运行的程序，重启会让它脱离 valgrind；在进程之外没有对应文件的程序，例如已删除的文件或 fexecve 的 memfd。静态程序如果用另一个程序替换掉自身，而新程序的参数以它自己的参数结尾（不带参数启动的静态程序换成任何程序都是如此），上报的仍是它自己。</p><hr><h2 id="windows-dll-注入与-api-钩子" tabindex="-1">Windows -- DLL 注入与 API 钩子 <a class="header-anchor" href="#windows-dll-注入与-api-钩子" aria-label="Permalink to &quot;Windows -- DLL 注入与 API 钩子&quot;">​</a></h2><p>Windows 钩子使用了与 Unix 完全不同的方法，因为 Windows 没有 <code>LD_PRELOAD</code> 的等价机制。catter 结合使用了：</p><ol><li><strong>DLL 注入</strong> -- 将钩子库加载到目标进程中</li><li><strong>基于 <a href="https://github.com/microsoft/Detours" target="_blank" rel="noreferrer">Microsoft Detours</a> 的 API 钩子</strong> -- 在这些进程内拦截 <code>CreateProcess</code> 调用</li></ol><p>Windows 钩子不运行 <code>catter-proxy</code>。它在调用方自己的 <code>CreateProcess</code> 调用中运行，在这里就能完成 <code>catter-proxy</code> 在 Unix 上做的事：通过会话的管道与 catter 通信，并亲自启动程序。catter 只要持有某个进程的句柄，Windows 就会把这个进程的退出码交给它，因此 catter 无需在每个程序旁边另起一个自己的进程来得知程序如何结束。</p><h3 id="钩子-dll" tabindex="-1">钩子 DLL <a class="header-anchor" href="#钩子-dll" aria-label="Permalink to &quot;钩子 DLL&quot;">​</a></h3><p>进程只会加载与自身架构相同的 DLL，因此每种架构各有一个钩子 DLL，都安装在 <code>catter.exe</code> 所在的目录：</p><table tabindex="0"><thead><tr><th>DLL</th><th>加载到</th></tr></thead><tbody><tr><td><code>catter-hook-x64.dll</code></td><td>x64 进程、在 ARM64 上模拟运行的 x64 进程、ARM64EC 程序</td></tr><tr><td><code>catter-hook-arm64.dll</code></td><td>原生 ARM64 进程</td></tr></tbody></table><p>catter 的每个 Windows 版本都同时带有这两个 DLL：在 Windows on ARM 上，一次构建中既有原生 ARM64 工具，也有模拟运行的 x64 工具。32 位（x86）进程目前还没有对应的钩子 DLL：它不加载钩子直接运行，与没有 catter 时一样，它启动的命令也不会被捕获。catter 会记录一条警告，写明是哪个程序。handler 丢弃这类程序的命令时，catter 会在调用方恢复该进程之前就立即结束它。</p><p>两个 DLL 构建时都不启用 AddressSanitizer，并把 C++ 运行时链接进 DLL 本身，只导入 Windows 自带的 DLL（包括 UCRT）：它们运行在构建的每个进程中，这些进程未必带有其他运行时 DLL；而且 Detours 在地址空间中搜索时会读到 ASan 的影子内存（shadow memory）。</p><h3 id="进程的会话" tabindex="-1">进程的会话 <a class="header-anchor" href="#进程的会话" aria-label="Permalink to &quot;进程的会话&quot;">​</a></h3><p>进程中的钩子从 catter 那里得知自己向哪个会话报告，而不是从环境变量中读取：catter 向它注入钩子的每个进程复制一份 Detours 载荷（payload），其中存有会话的管道和该进程所运行命令的 ID；对于不该运行的命令，存的则是钩子一加载就让进程结束时使用的退出码。构建的环境保持构建自己设置的样子；即使调用方把自己的环境原样传给程序，每个程序也会得到自己的命令 ID。</p><h3 id="dll-注入过程" tabindex="-1">DLL 注入过程 <a class="header-anchor" href="#dll-注入过程" aria-label="Permalink to &quot;DLL 注入过程&quot;">​</a></h3><p>catter 把钩子注入它自己启动的构建命令，以及钩子启动的每个程序：</p><ol><li><p><strong>进程处于挂起状态</strong>。catter 用 kotatsu 的 <code>kota::sys::spawn</code> 启动构建命令，其 <code>windows_before_start</code> 回调拿到已创建的进程：进程已在自己的 job 对象中，主线程尚未运行。钩子启动的程序由钩子以挂起状态创建，钩子把它的进程 ID 发给 catter，catter 随后打开该进程。</p></li><li><p><strong>确定进程的架构</strong>。<code>GetProcessInformation(ProcessMachineTypeInfo)</code> 给出进程所运行代码的机器类型：在 ARM64 上模拟运行的 x64 进程和 ARM64EC 进程得到的都是 x64，而 <code>IsWow64Process2</code> 无法把它们与原生 ARM64 进程区分开。Windows 10 没有 <code>ProcessMachineTypeInfo</code>，也不支持模拟 x64，在那里由 <code>IsWow64Process2</code> 给出架构。</p></li><li><p><strong>把钩子 DLL 加入进程的导入表</strong>。<code>DetourUpdateProcessWithDll()</code> 把对应架构的 DLL 加入挂起的可执行文件的导入表，这样加载器会在程序自身的任何代码运行之前映射它。加载器按进程自己的 ANSI 代码页读取导入表里的 DLL 路径，而程序可以把这个代码页设为 UTF-8，所以路径必须是纯 ASCII：含非 ASCII 字符的路径改用它的 8.3 短文件名；在不保留短文件名的卷上，则改用复制到 catter 数据目录中的那份 DLL。</p></li><li><p><strong>把会话交给钩子</strong>。<code>DetourCopyPayloadToProcess()</code> 把会话的管道和命令的 ID 复制到进程中。</p></li><li><p><strong>恢复主线程</strong>。构建命令在回调返回后由 <code>spawn</code> 恢复；钩子启动的程序在 catter 答复后由钩子恢复。加载器把钩子 DLL 与程序的其他导入项一同映射，钩子在程序入口点运行之前就已激活。</p></li></ol><h3 id="被钩住的-windows-api" tabindex="-1">被钩住的 Windows API <a class="header-anchor" href="#被钩住的-windows-api" aria-label="Permalink to &quot;被钩住的 Windows API&quot;">​</a></h3><p>钩子 DLL 在 <code>DLL_PROCESS_ATTACH</code> 期间用 Detours 为以下函数安装钩子，全部在同一个事务中完成：</p><ul><li><strong><code>CreateProcessA()</code></strong> -- ANSI 版本的进程创建函数</li><li><strong><code>CreateProcessW()</code></strong> -- 宽字符版本的进程创建函数</li></ul><p>程序以其他账户的令牌（token）启动的进程（<code>CreateProcessAsUser</code>、<code>CreateProcessWithTokenW</code>、<code>CreateProcessWithLogonW</code>）不带钩子运行，也不会被捕获：那个账户可能访问不到会话的管道。</p><p>Detours 的工作原理：</p><ol><li>保存目标函数的前几条指令</li><li>将其覆写为跳转到替代函数的指令</li><li>提供一个 trampoline（跳板），包含保存的指令及跳回原函数的跳转，使原始函数仍可被调用</li></ol><h3 id="钩子替代逻辑" tabindex="-1">钩子替代逻辑 <a class="header-anchor" href="#钩子替代逻辑" aria-label="Permalink to &quot;钩子替代逻辑&quot;">​</a></h3><p>当被钩住的进程调用 <code>CreateProcessA</code> 或 <code>CreateProcessW</code> 时：</p><ol><li><p><strong>解析程序</strong>。钩子用 <code>resolve_program()</code> 解析：<code>lpApplicationName</code> 从当前目录补全为绝对路径；没有它时，取命令行的第一个词，按 <code>CreateProcess</code> 的方式查找（kotatsu 的 <code>find_create_process_program</code>：程序所在目录、当前目录、系统目录、Windows 目录，最后是 <code>PATH</code>）；不带引号的名字会依次读到每个空白处，和 <code>CreateProcess</code> 读 <code>C:\\Program Files\\tool.exe a b</code> 的方式一样。找不到这样的文件时，这次调用原样交给原始的 <code>CreateProcess</code>，失败方式和没有 catter 时相同。</p></li><li><p><strong>连接会话</strong>。钩子打开会话的管道。打不开时（例如早先的会话启动的构建服务器，而那个会话已经结束），这次调用原样交给原始的 <code>CreateProcess</code>，程序运行但不被捕获。</p></li><li><p><strong>询问 catter</strong>。钩子按 <code>CreateProcess</code> 将要启动的样子读取命令：命令行中的参数、环境块（没有时取调用方自己的环境）和工作目录。它发送 <code>MAKE_DECISION</code>，然后等待 catter 的答复；除此之外，<code>CreateProcess</code> 本身不等待任何别的东西。</p></li><li><p><strong>以挂起状态启动程序</strong>。钩子用调用方自己的参数、标志、句柄和 <code>STARTUPINFO</code> 调用原始的 <code>CreateProcess</code>，只额外加上 <code>CREATE_SUSPENDED</code>。handler 改动过的部分会重新写入：程序，以命令的工作目录为当前目录，按 <code>CreateProcess</code> 的方式查找；命令行，仅当 handler 改了参数时才由参数重新拼出；环境；工作目录。其余部分保持调用方写下的样子，因此 <code>cmd.exe</code> 以及其他自己读取命令行的程序，读到的和没有 catter 时一样。程序无法启动时，钩子报告这一错误（<code>REPORT_ERROR</code>），并让这次调用以系统给出的错误失败。</p></li><li><p><strong>交给 catter 接管</strong>。钩子发送进程 ID（<code>started</code>）。catter 打开该进程，让它按决定的方式运行：注入钩子；对于不该运行的命令，注入的钩子会在加载后立即以退出码 0（已丢弃）或 1（会话已失败）结束进程，赶在程序自身的代码运行之前。随后 catter 等待进程退出，并把它的退出码告诉各个 handler。catter 无法让程序按决定的方式运行时，会报告错误，钩子则以退出码 1 结束该程序。</p></li><li><p><strong>恢复程序</strong>。除非调用方要求以挂起状态创建进程，钩子会恢复主线程，然后返回。调用方拿到的是程序自己的进程和线程句柄及 ID。</p></li></ol><p>调用方持有的就是程序本身，与没有 catter 时一样。调用方对自己启动的进程所做的事，也都和没有 catter 时一样有效：例如 MSBuild 的 tracker，它以挂起状态启动每个工具，在工具运行前注入文件追踪；又如调试器，或记下各个任务进程 ID 的构建工具。</p><h3 id="与-unix-的关键区别" tabindex="-1">与 Unix 的关键区别 <a class="header-anchor" href="#与-unix-的关键区别" aria-label="Permalink to &quot;与 Unix 的关键区别&quot;">​</a></h3><p>在 Unix 上，<code>LD_PRELOAD</code> 是一个由所有子进程自动继承的环境变量。钩子默认具有&quot;传染性&quot; -- 每个子进程都会被钩住。</p><p>在 Windows 上没有这样的机制。钩子 DLL 必须显式注入到每个新进程中：钩子启动的每个程序还处于挂起状态时，catter 就把钩子注入其中。链上可以交替出现不同架构的进程：每个进程都会得到与自身架构对应的钩子 DLL。</p><h3 id="dll-生命周期" tabindex="-1">DLL 生命周期 <a class="header-anchor" href="#dll-生命周期" aria-label="Permalink to &quot;DLL 生命周期&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DLL_PROCESS_ATTACH:</span></span>
<span class="line"><span>  DetourRestoreAfterWith()   -- Restore the import table catter changed</span></span>
<span class="line"><span>  DetourFindPayloadEx()      -- Read the session catter copied into the process</span></span>
<span class="line"><span>  TerminateProcess(...)      -- End a process whose command is not to run</span></span>
<span class="line"><span>  DetourTransactionBegin()</span></span>
<span class="line"><span>  DetourAttach(...)          -- Hook CreateProcessA and CreateProcessW</span></span>
<span class="line"><span>  DetourTransactionCommit()  -- Activate all hooks at once</span></span></code></pre></div><p>在 attach 阶段调用 <code>DisableThreadLibraryCalls()</code> 以抑制 <code>DLL_THREAD_ATTACH</code> 和 <code>DLL_THREAD_DETACH</code> 通知，减少运行开销。该 DLL 是可执行文件的导入项，只随进程一起卸载，因此 <code>DLL_PROCESS_DETACH</code> 时没有需要撤销的操作。它导出序号为 1 的符号，凡是由 Detours 注入的 DLL 都必须如此。</p><h2 id="平台对比" tabindex="-1">平台对比 <a class="header-anchor" href="#平台对比" aria-label="Permalink to &quot;平台对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方面</th><th>Linux</th><th>macOS</th><th>Windows</th></tr></thead><tbody><tr><td>钩子库</td><td><code>libcatter-hook-unix.so</code></td><td><code>libcatter-hook-unix.dylib</code></td><td><code>catter-hook-{x64,arm64}.dll</code></td></tr><tr><td>注入方式</td><td><code>LD_PRELOAD</code> 环境变量</td><td><code>DYLD_INSERT_LIBRARIES</code> 环境变量</td><td><code>DetourUpdateProcessWithDll</code></td></tr><tr><td>函数替换</td><td><code>dlsym(RTLD_NEXT, ...)</code></td><td><code>DYLD_INTERPOSE</code> 宏</td><td>Detours trampoline 钩子</td></tr><tr><td>拦截的 API</td><td><code>execve</code>、<code>execvp</code>、<code>posix_spawn</code> 等</td><td>与 Linux 相同</td><td><code>CreateProcessA</code>、<code>CreateProcessW</code></td></tr><tr><td>递归钩子</td><td>自动（环境变量继承）</td><td>自动（环境变量继承）</td><td>显式（每个进程重新注入 DLL）</td></tr><tr><td>会话</td><td><code>__key_catter_proxy_path_v1</code>、<code>__key_catter_command_id_v1</code>、<code>__key_catter_ipc_v1</code></td><td>与 Linux 相同</td><td>每个进程中的一份 Detours 载荷</td></tr><tr><td>由谁启动命令</td><td><code>catter-proxy</code></td><td>与 Linux 相同</td><td>钩子，在调用方自己的调用中</td></tr></tbody></table>`,73)])])}const u=o(a,[["render",r]]);export{_ as __pageData,u as default};
